<script lang="ts">
  import { store } from '../lib/store.svelte';

  let { text, size = 220 }: { text: string; size?: number } = $props();
  let svg = $state('');

  $effect(() => {
    const value = text;
    if (!value) {
      svg = '';
      return;
    }
    store.qr(value).then((s) => {
      if (value === text) svg = s;
    });
  });
</script>

<div class="qr" style="width:{size}px;height:{size}px">
  <!-- SVG generated by the Rust qrcode crate from our own URL; no user markup. -->
  {@html svg}
  <span class="scan"></span>
</div>

<style>
  .qr {
    position: relative;
    border-radius: 22px;
    overflow: hidden;
    background: #fff;
    padding: 6px;
    box-shadow:
      0 0 0 1px rgba(255, 255, 255, 0.4),
      0 20px 70px -20px color-mix(in oklab, var(--accent-2) 90%, transparent);
  }
  .qr :global(svg) {
    width: 100%;
    height: 100%;
    display: block;
  }
  .scan {
    position: absolute;
    inset-inline: 0;
    height: 30%;
    top: -30%;
    background: linear-gradient(180deg, transparent, color-mix(in oklab, var(--accent-1) 22%, transparent), transparent);
    animation: scan 3.2s var(--ease) infinite;
    pointer-events: none;
  }
  @keyframes scan {
    to {
      top: 100%;
    }
  }
</style>
